//! UI 0.4 design tokens: themes, colours, type, spacing, radii and shell sizes.
//!
//! Generated by `scripts/generate_tokens_04.py` from
//! `design/ontwerp-0.4/tokens-0.4.json` (version 0.4.0). Do not edit by hand;
//! change the JSON and run the generator. This module is the start of library 0.4
//! and is independent of the prototype theme in [`crate::theme`].
#![allow(clippy::excessive_precision)] // Preserve source RGB and opacity values.
use iced::{Color, Shadow, Vector};
use serde::{Deserialize, Serialize};

pub const VERSION: &str = "0.4.0";

/// The five UI 0.4 themes.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ThemeId {
    #[default]
    Light,
    Dark,
    Blueprint,
    HighContrastDark,
    HighContrastLight,
}

impl ThemeId {
    pub const ALL: [Self; 5] = [
        Self::Light,
        Self::Dark,
        Self::Blueprint,
        Self::HighContrastDark,
        Self::HighContrastLight,
    ];
    pub fn tokens(self) -> &'static ThemeTokens {
        match self {
            Self::Light => &LIGHT,
            Self::Dark => &DARK,
            Self::Blueprint => &BLUEPRINT,
            Self::HighContrastDark => &HIGH_CONTRAST_DARK,
            Self::HighContrastLight => &HIGH_CONTRAST_LIGHT,
        }
    }
    /// Stable key, as used in settings files and the CSS attribute `data-oa-theme`.
    pub fn key(self) -> &'static str {
        self.tokens().key
    }
    /// Dutch display name.
    pub fn name(self) -> &'static str {
        self.tokens().name
    }
    pub fn from_key(key: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|t| t.key() == key)
    }
    /// An iced theme whose palette follows these tokens.
    pub fn iced(self) -> iced::Theme {
        let c = &self.tokens().color;
        iced::Theme::custom(
            self.name().to_string(),
            iced::theme::Palette {
                background: c.panel,
                text: c.text,
                primary: c.accent,
                success: c.success,
                danger: c.error,
            },
        )
    }
}

impl std::fmt::Display for ThemeId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

