/// One layer of a CSS-style box shadow. Layers with spread and no blur are rings.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ShadowLayer {
    pub inset: bool,
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub color: Color,
}

impl ShadowLayer {
    /// The layer as an iced shadow. iced draws no spread or inset, so callers draw rings as borders.
    pub fn iced(&self) -> Shadow {
        Shadow {
            color: self.color,
            offset: Vector::new(self.x, self.y),
            blur_radius: self.blur,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Shadows {
    pub panel: &'static [ShadowLayer],
    pub popup: &'static [ShadowLayer],
    pub dialog: &'static [ShadowLayer],
}

impl Shadows {
    /// The first outer blurred layer, which iced can draw directly.
    pub fn drop_shadow(layers: &[ShadowLayer]) -> Option<Shadow> {
        layers
            .iter()
            .find(|l| !l.inset && l.blur > 0.0)
            .map(ShadowLayer::iced)
    }
}

/// Everything one theme defines.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ThemeTokens {
    pub key: &'static str,
    pub name: &'static str,
    pub dark: bool,
    pub high_contrast: bool,
    /// Selection is an outline instead of a tint (High contrast).
    pub selection_outline: bool,
    /// Disabled controls get a dashed border instead of fading (High contrast).
    pub disabled_dashed: bool,
    pub color: Palette,
    pub shadow: Shadows,
    pub overlay: Color,
}

