/// User setting Werkruimte. The default follows the theme; High contrast ignores it.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum WorkspaceSetting {
    #[default]
    Theme,
    Light,
    Dark,
}

impl WorkspaceSetting {
    pub const ALL: [Self; 3] = [Self::Theme, Self::Light, Self::Dark];
    pub fn name(self) -> &'static str {
        match self {
            Self::Theme => "Volgt thema",
            Self::Light => "Altijd licht",
            Self::Dark => "Altijd donker",
        }
    }
}

impl std::fmt::Display for WorkspaceSetting {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

/// User setting Statusbalk. The default follows the theme; High contrast ignores it.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum StatusbarSetting {
    #[default]
    Theme,
    Dark,
}

impl StatusbarSetting {
    pub const ALL: [Self; 2] = [Self::Theme, Self::Dark];
    pub fn name(self) -> &'static str {
        match self {
            Self::Theme => "Volgt thema",
            Self::Dark => "Altijd donker",
        }
    }
}

impl std::fmt::Display for StatusbarSetting {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

impl ThemeTokens {
    /// The palette after the Werkruimte and Statusbalk settings.
    ///
    /// A workspace of the other kind than the theme also takes that kind's
    /// `accent_text`, so accent text in the workspace keeps its contrast.
    pub fn palette(&self, workspace: WorkspaceSetting, statusbar: StatusbarSetting) -> Palette {
        let mut c = self.color;
        if self.high_contrast {
            return c;
        }
        match workspace {
            WorkspaceSetting::Theme => {}
            WorkspaceSetting::Light => {
                c.workspace = Color {
                    r: 1.000000000,
                    g: 1.000000000,
                    b: 1.000000000,
                    a: 1.000000000,
                };
                c.workspace_text = Color {
                    r: 0.164705882,
                    g: 0.164705882,
                    b: 0.196078431,
                    a: 1.000000000,
                };
            }
            WorkspaceSetting::Dark => {
                c.workspace = Color {
                    r: 0.149019608,
                    g: 0.149019608,
                    b: 0.176470588,
                    a: 1.000000000,
                };
                c.workspace_text = Color {
                    r: 0.929411765,
                    g: 0.921568627,
                    b: 0.909803922,
                    a: 1.000000000,
                };
            }
        }
        if let StatusbarSetting::Dark = statusbar {
            c.statusbar = Color {
                r: 0.164705882,
                g: 0.164705882,
                b: 0.196078431,
                a: 1.000000000,
            };
            c.statusbar_text = Color {
                r: 0.831372549,
                g: 0.819607843,
                b: 0.800000000,
                a: 1.000000000,
            };
        }
        c
    }

    /// Accent text colour inside the workspace for a Werkruimte setting.
    pub fn workspace_accent_text(&self, workspace: WorkspaceSetting) -> Color {
        match workspace {
            _ if self.high_contrast => self.color.accent_text,
            WorkspaceSetting::Light if self.dark => LIGHT.color.accent_text,
            WorkspaceSetting::Dark if !self.dark => DARK.color.accent_text,
            _ => self.color.accent_text,
        }
    }
}

