#[cfg(test)]
mod tests {
    use super::*;

    fn luminance(c: Color) -> f32 {
        let ch = |v: f32| {
            if v <= 0.04045 {
                v / 12.92
            } else {
                ((v + 0.055) / 1.055).powf(2.4)
            }
        };
        0.2126 * ch(c.r) + 0.7152 * ch(c.g) + 0.0722 * ch(c.b)
    }

    fn contrast(a: Color, b: Color) -> f32 {
        let (x, y) = (luminance(a), luminance(b));
        (x.max(y) + 0.05) / (x.min(y) + 0.05)
    }

    #[test]
    fn keys_round_trip_and_names_are_dutch() {
        for theme in ThemeId::ALL {
            assert_eq!(ThemeId::from_key(theme.key()), Some(theme));
            let json = serde_json::to_string(&theme).unwrap();
            assert_eq!(json, format!("\"{}\"", theme.key()));
        }
        assert_eq!(ThemeId::default().name(), "Licht");
    }

    #[test]
    fn body_text_meets_its_minimum_in_every_theme_and_setting() {
        for theme in ThemeId::ALL {
            let t = theme.tokens();
            let min = if t.high_contrast { 7.0 } else { 4.5 };
            for ws in WorkspaceSetting::ALL {
                for sb in StatusbarSetting::ALL {
                    let c = t.palette(ws, sb);
                    assert!(contrast(c.text, c.panel) >= min, "{theme} text");
                    assert!(
                        contrast(c.workspace_text, c.workspace) >= min,
                        "{theme} {ws:?} workspace"
                    );
                    assert!(
                        contrast(t.workspace_accent_text(ws), c.workspace) >= 4.5,
                        "{theme} {ws:?} accent"
                    );
                    assert!(
                        contrast(c.statusbar_text, c.statusbar) >= 4.5,
                        "{theme} {sb:?} statusbar"
                    );
                    assert!(
                        contrast(c.text_on_accent, c.accent) >= 4.5,
                        "{theme} primary button"
                    );
                }
            }
        }
    }

    #[test]
    fn high_contrast_ignores_settings() {
        let t = HIGH_CONTRAST_DARK;
        assert_eq!(
            t.palette(WorkspaceSetting::Light, StatusbarSetting::Dark),
            t.color
        );
        assert!(t.selection_outline && t.disabled_dashed);
        assert!(Shadows::drop_shadow(t.shadow.panel).is_none());
        assert!(Shadows::drop_shadow(LIGHT.shadow.dialog).is_some());
    }
}
